import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.lxr64Vqo.js";const h=JSON.parse('{"title":"☁️ True Cloud Sync & 24/7 Standby","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cloud-sync.md","filePath":"guide/cloud-sync.md","lastUpdated":1795112636000}'),r={name:"guide/cloud-sync.md"};function i(s,e,d,l,c,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="☁️-true-cloud-sync-24-7-standby" tabindex="-1">☁️ True Cloud Sync &amp; 24/7 Standby <a class="header-anchor" href="#☁️-true-cloud-sync-24-7-standby" aria-label="Permalink to &quot;☁️ True Cloud Sync &amp; 24/7 Standby&quot;">​</a></h1><p>NoxMedia is designed to run seamlessly in the background as an always-available home media server, keeping your watch states and library synchronized across all your screens.</p><hr><h2 id="🔄-true-cloud-sync" tabindex="-1">🔄 True Cloud Sync <a class="header-anchor" href="#🔄-true-cloud-sync" aria-label="Permalink to &quot;🔄 True Cloud Sync&quot;">​</a></h2><p>Whether you watch on an Apple TV in your living room, an iPad in bed, or your Android phone on the go, NoxMedia keeps your viewing session unified:</p><ul><li><strong>Resume Playback</strong>: Pause on Infuse Apple TV, resume at the exact second on Stremio mobile or Nuvio.</li><li><strong>Watched / Unwatched State</strong>: Marking an episode or movie as watched reflects everywhere automatically.</li><li><strong>Cross-Device Scrobbling</strong>: Supports Jellyfin watch session reporting and optional Trakt scrobbling.</li></ul><hr><h2 id="⚡-24-7-background-standby-mode" tabindex="-1">⚡ 24/7 Background Standby Mode <a class="header-anchor" href="#⚡-24-7-background-standby-mode" aria-label="Permalink to &quot;⚡ 24/7 Background Standby Mode&quot;">​</a></h2><p>Android&#39;s aggressive battery optimizations can sometimes put background processes to sleep. NoxMedia includes built-in safeguards to maintain an uninterrupted server uptime:</p><h3 id="_1-foreground-service" tabindex="-1">1. Foreground Service <a class="header-anchor" href="#_1-foreground-service" aria-label="Permalink to &quot;1. Foreground Service&quot;">​</a></h3><p>When the server toggle is enabled, NoxMedia launches a low-overhead Android Foreground Service with a persistent notification, preventing the OS from terminating the process.</p><h3 id="_2-battery-optimization-exemption" tabindex="-1">2. Battery Optimization Exemption <a class="header-anchor" href="#_2-battery-optimization-exemption" aria-label="Permalink to &quot;2. Battery Optimization Exemption&quot;">​</a></h3><p>For true 24/7 reliability (especially when using an old phone as a dedicated server):</p><ol><li>Go to your phone&#39;s <strong>Settings</strong> → <strong>Apps</strong> → <strong>NoxMedia</strong>.</li><li>Tap <strong>Battery</strong> → Select <strong>Unrestricted</strong> (or &quot;Don&#39;t Optimize&quot;).</li><li>Disable any manufacturer-specific aggressive RAM cleaners (e.g., Xiaomi MIUI/HyperOS Autostart, Samsung Put to Sleep).</li></ol><h3 id="_3-wi-fi-power-management" tabindex="-1">3. Wi-Fi Power Management <a class="header-anchor" href="#_3-wi-fi-power-management" aria-label="Permalink to &quot;3. Wi-Fi Power Management&quot;">​</a></h3><p>Ensure your host device stays connected to Wi-Fi while sleeping:</p><ul><li>Keep the device connected to a charger when acting as a permanent home hub.</li><li>In Wi-Fi advanced settings, set Wi-Fi sleep policy to <strong>Always on during sleep</strong>.</li></ul>',17)])])}const g=a(r,[["render",i]]);export{h as __pageData,g as default};
